{
  "decisions": [
    {
      "requirement_id": "ETC-101",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement specifies a behavioral response (immediate fulfillment) to a specific input condition (absence of start sub-conditions) which can be verified by executing the system with such a message and observing the state."
    },
    {
      "requirement_id": "ETC-102",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement defines two distinct behavioral outcomes for driver acknowledgement depending on the message definition, which can be verified by simulating driver input and observing the display termination logic."
    },
    {
      "requirement_id": "ETC-103",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement describes a conditional behavior (not displaying the message) based on the state of the end condition at the moment the start condition is fulfilled, which is verifiable by setting up the specific timing and condition states."
    },
    {
      "requirement_id": "ETC-104",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement specifies how the OBU calculates the display length based on location data, which can be verified by providing specific location inputs and measuring the resulting display duration or distance."
    },
    {
      "requirement_id": "ETC-105",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement mandates the transmission of a specific report with specific content upon driver acknowledgement, which can be verified by capturing the communication output to the RBC."
    },
    {
      "requirement_id": "ETC-106",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement defines a rejection behavior for duplicate message identifiers, which can be verified by sending a new message with a conflicting ID and observing the OBU's rejection response."
    },
    {
      "requirement_id": "ETC-107",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement specifies complex logic for deleting or keeping Mode Profiles based on the infill reference location, which can be verified by simulating infill scenarios with different reference positions and checking the resulting profile states."
    },
    {
      "requirement_id": "ETC-108",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement defines the OBU's treatment of the Mode Profile start as a temporary EOA and the calculation of temporary SvL, which can be verified by monitoring the OBU's speed supervision and EOA status during the transition."
    },
    {
      "requirement_id": "ETC-109",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement specifies that new LX information with the same identity replaces the old one, which can be verified by sending two LX messages with the same identity and checking the stored data."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KDH-051",
      "methods": [
        "Test"
      ],
      "rationale": "HttpOnly attribute presence and Set-Cookie header usage are verified by inspecting HTTP responses during a live session."
    },
    {
      "requirement_id": "KDH-052",
      "methods": [
        "Test"
      ],
      "rationale": "The presence and values of the Strict-Transport-Security header are verified by inspecting HTTP responses from the portal."
    },
    {
      "requirement_id": "KDH-053",
      "methods": [
        "Test"
      ],
      "rationale": "File upload validation is verified by submitting files with mismatched extensions and contents to observe rejection behavior."
    },
    {
      "requirement_id": "KDH-054",
      "methods": [
        "Test"
      ],
      "rationale": "Image size validation is verified by uploading images exceeding the defined pixel limits to observe rejection."
    },
    {
      "requirement_id": "KDH-055",
      "methods": [
        "Test"
      ],
      "rationale": "User enumeration prevention is verified by comparing error messages, HTTP codes, and response times for valid and invalid credentials."
    },
    {
      "requirement_id": "KDH-056",
      "methods": [
        "Test"
      ],
      "rationale": "Help Desk permissions are verified by attempting to initiate resets and change passwords to confirm only initiation is allowed."
    },
    {
      "requirement_id": "KDH-057",
      "methods": [
        "Test"
      ],
      "rationale": "Session token rotation is verified by authenticating and checking that a new token is issued and the old one is invalidated."
    },
    {
      "requirement_id": "KDH-058",
      "methods": [
        "Test"
      ],
      "rationale": "Session invalidation is verified by attempting to use a session token after logout or expiration to confirm access is denied."
    },
    {
      "requirement_id": "KDH-059",
      "methods": [
        "Test"
      ],
      "rationale": "Reauthentication requirement is verified by attempting sensitive changes after 5 minutes of inactivity to confirm the block and subsequent success after reauth."
    },
    {
      "requirement_id": "KDH-060",
      "methods": [
        "Test"
      ],
      "rationale": "Access control is verified by attempting to access other users' data using modified identifiers to confirm denial of unauthorized access."
    },
    {
      "requirement_id": "KDH-061",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Text alternatives for non-text content are verified by inspecting the HTML markup for alt attributes and ARIA labels."
    },
    {
      "requirement_id": "KDH-062",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Programmatic determination of structure is verified by inspecting the HTML markup for semantic elements like tables, headers, and lists."
    },
    {
      "requirement_id": "KDH-063",
      "methods": [
        "Test"
      ],
      "rationale": "Orientation independence is verified by rotating the device or resizing the window to ensure content remains usable in both orientations."
    },
    {
      "requirement_id": "KDH-064",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Form field purpose identification is verified by inspecting the HTML markup for autocomplete attributes on input fields."
    },
    {
      "requirement_id": "KDH-065",
      "methods": [
        "Analiz"
      ],
      "rationale": "Contrast ratios are verified by calculating the luminance difference between text and background colors using a contrast checker tool."
    },
    {
      "requirement_id": "KDH-066",
      "methods": [
        "Test"
      ],
      "rationale": "Text resizing is verified by zooming the browser to 200% to ensure no content or functionality is lost."
    },
    {
      "requirement_id": "KDH-067",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Use of text instead of images is verified by inspecting the HTML markup to ensure information is conveyed via text elements where possible."
    },
    {
      "requirement_id": "KDH-068",
      "methods": [
        "Test"
      ],
      "rationale": "Spacing adjustments are verified by applying CSS overrides for line height, paragraph spacing, and letter spacing to ensure no content loss."
    },
    {
      "requirement_id": "KDH-069",
      "methods": [
        "Test"
      ],
      "rationale": "Keyboard operability is verified by navigating and interacting with all portal functions using only the keyboard without time limits."
    },
    {
      "requirement_id": "KDH-070",
      "methods": [
        "Test"
      ],
      "rationale": "Session timeout warning is verified by waiting 25 minutes of inactivity to observe the dialog, screen reader announcement, and extension functionality."
    },
    {
      "requirement_id": "KDH-071",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Page titles are verified by inspecting the HTML <title> tag of each page to ensure it describes the page content."
    },
    {
      "requirement_id": "KDH-072",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Link purpose clarity is verified by inspecting the link text and associated context in the HTML markup to ensure the purpose is clear."
    },
    {
      "requirement_id": "KDH-073",
      "methods": [
        "Test"
      ],
      "rationale": "Focus visibility is verified by navigating with the keyboard to ensure a visible focus indicator is present on all interactive elements."
    },
    {
      "requirement_id": "KDH-074",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Page language is verified by inspecting the HTML <html> tag for the lang attribute to ensure the default language is specified."
    },
    {
      "requirement_id": "KDH-075",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Section language is verified by inspecting the HTML markup for lang attributes on elements containing text in a different language than the page default."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KDH-101",
      "methods": [
        "Test"
      ],
      "rationale": "Hareketsizlik kilidi ve FIDO2/PIN ile yeniden kimlik doğrulama akışının, sistem çalıştırılarak ve girdi verilerek gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KDH-102",
      "methods": [
        "Test"
      ],
      "rationale": "Oturumun belirlenen koşullarda otomatik sonlandırılmasının, sistem üzerinde süre ve koşul manipülasyonu yapılarak test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-103",
      "methods": [
        "Test"
      ],
      "rationale": "Denetim kayıtlarının gerekli alanları (tür, zaman, yer, kaynak, sonuç, kimlik) içerip içermediğinin, olaylar tetiklenerek ve loglar incelenerek doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-104",
      "methods": [
        "Test"
      ],
      "rationale": "Zaman damgalarının UTC formatında ve doğru ayrıntı düzeyinde kaydedilip kaydedilmediğinin, sistem saatleri ve loglar üzerinden test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-105",
      "methods": [
        "Test"
      ],
      "rationale": "Yetkisiz erişim, değişiklik veya silme denemelerinin algılanıp algılanmadığının ve uyarıların gönderilip gönderilmediğinin, saldırı senaryolarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-106",
      "methods": [
        "Test"
      ],
      "rationale": "Parola ve OTP girişlerinin ekranda gizlenip gizlenmediğinin, kullanıcı arayüzü üzerinden girdi vererek ve gözlemleyerek test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-107",
      "methods": [
        "Test"
      ],
      "rationale": "Hassas işlemler öncesi tazelik süresi dolunca yeniden kimlik doğrulama zorunluluğunun, süre manipülasyonu ve işlem denemesiyle test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-108",
      "methods": [
        "Test"
      ],
      "rationale": "Veri iletiminin şifreli ve bütünlüğü korunarak yapılıp yapılmadığının, ağ trafiği analizi ve penetrasyon testleriyle doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-109",
      "methods": [
        "Test"
      ],
      "rationale": "Geçersiz, bozuk veya zararlı girdilerin sistemin reddedip reddetmediğinin, çeşitli hata senaryolarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-110",
      "methods": [
        "Test"
      ],
      "rationale": "Hata mesajlarının kullanıcıya genel bilgi verip vermediğinin ve ayrıntılı logların yetkili personele gösterilip gösterilmediğinin, hata senaryolarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-111",
      "methods": [
        "Test"
      ],
      "rationale": "Oturum sonu uyarısı, taslak kaydı ve veri kaybı olmadan devam etme akışının, kullanıcı senaryolarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-112",
      "methods": [
        "Test"
      ],
      "rationale": "CAPTCHA kullanılmadığının ve bot eşiği aşıldığında etkileşimsiz kanıt veya nesne tanıma sorgusunun doğru sırayla istenip istenmediğinin, bot simülasyonlarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-113",
      "methods": [
        "Test"
      ],
      "rationale": "Ödeme sonucunun yalnızca imzalı bildirimle kabul edildiğinin ve belirsiz durumlarda bekleme modunda kalındığının, KÖA entegrasyon senaryolarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-114",
      "methods": [
        "Test"
      ],
      "rationale": "AAL2 altı veya eksik alanlı e-Devlet belirtecinin sınırlı kipte oturum açtığının ve kişisel verilerin gizlendiğinin, farklı AAL düzeyleriyle test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-115",
      "methods": [
        "Test"
      ],
      "rationale": "Parola geçerlilik süresinin yalnızca şirket temsilcilerine uygulandığının, bildirimlerin ve sızıntı durumunda zorunlu değişikliğin, hesap senaryolarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-116",
      "methods": [
        "Test"
      ],
      "rationale": "TOTP kodlarının yalnızca geçerli ve bir önceki adımda kabul edildiğinin ve tek kullanımlık olduğunun, zaman ve kod manipülasyonuyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-117",
      "methods": [
        "Test"
      ],
      "rationale": "Başarısız deneme eşiğinin doğrulayıcıyı devre dışı bıraktığının ve hesap kurtarma akışının, tekrarlı başarısız giriş denemeleriyle test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-118",
      "methods": [
        "Test"
      ],
      "rationale": "Farklı AAL düzeylerinde hareketsizlik sonrası yeniden doğrulama akışlarının (parola vs e-Devlet) ve oturum sırrı silinmesinin, oturum senaryolarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-119",
      "methods": [
        "Test"
      ],
      "rationale": "Eşzamanlı oturum sınırının aşıldığında en eski oturumun sonlandırıldığının ve kullanıcıya/SIEM'e bildiriminin, çoklu oturum senaryolarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-120",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, boyut ve sayı sınırlarının uygulandığının ve ret mesajlarının doğru iletildiğinin, çeşitli dosya yükleme senaryolarıyla test edilmesi gerekir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KDH-001",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement mandates the availability of specific authentication options, which is verified by executing the login flow and observing the presented choices."
    },
    {
      "requirement_id": "KDH-002",
      "methods": [
        "Test"
      ],
      "rationale": "The system's ability to enforce multi-factor or two-factor authentication at AAL2 is verified by attempting logins with valid and invalid factor combinations."
    },
    {
      "requirement_id": "KDH-003",
      "methods": [
        "Test"
      ],
      "rationale": "Periodic reauthentication behavior based on inactivity and overall timeouts is verified by simulating user sessions with specific idle and active durations."
    },
    {
      "requirement_id": "KDH-004",
      "methods": [
        "Test"
      ],
      "rationale": "The sending of notifications upon account recovery is verified by triggering a recovery event and observing the delivery of the notification."
    },
    {
      "requirement_id": "KDH-005",
      "methods": [
        "Test"
      ],
      "rationale": "The distribution of notifications to registered addresses (excluding postal) is verified by triggering a notification event and checking the recipients."
    },
    {
      "requirement_id": "KDH-006",
      "methods": [
        "Test"
      ],
      "rationale": "The independence of the VBP session from the e-Devlet assertion validity window is verified by maintaining a VBP session after the e-Devlet assertion expires."
    },
    {
      "requirement_id": "KDH-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The content of the assertion request, specifically the inclusion of the VBP identifier and cryptographic nonce, is verified by inspecting the network traffic or code implementation."
    },
    {
      "requirement_id": "KDH-008",
      "methods": [
        "Test"
      ],
      "rationale": "The validation of the assertion audience is verified by attempting to inject an assertion generated for a different relying party and observing the rejection."
    },
    {
      "requirement_id": "KDH-009",
      "methods": [
        "Test"
      ],
      "rationale": "The enforcement of the binding process for changing the SMS telephone number is verified by attempting to change the number without completing the required authentication steps."
    },
    {
      "requirement_id": "KDH-010",
      "methods": [
        "Test"
      ],
      "rationale": "The ability to bind multiple authenticators is verified by adding more than one authenticator to a single account and confirming their presence."
    },
    {
      "requirement_id": "KDH-011",
      "methods": [
        "Test"
      ],
      "rationale": "The required authentication level for binding a new authenticator is verified by attempting to bind an authenticator at different AAL levels and observing the system's response."
    },
    {
      "requirement_id": "KDH-012",
      "methods": [
        "Test"
      ],
      "rationale": "The sending of an independent notification upon adding an authenticator is verified by adding a new authenticator and checking for the notification via a separate channel."
    },
    {
      "requirement_id": "KDH-013",
      "methods": [
        "Test"
      ],
      "rationale": "The invalidation of a confirmation code after successful use is verified by using a code and then attempting to reuse it within its validity period."
    },
    {
      "requirement_id": "KDH-014",
      "methods": [
        "Test"
      ],
      "rationale": "The validation of assertion signatures is verified by presenting an assertion with an invalid or tampered signature and observing the rejection."
    },
    {
      "requirement_id": "KDH-015",
      "methods": [
        "Test"
      ],
      "rationale": "Replay protection is verified by submitting the same valid e-Devlet assertion twice and observing the rejection of the second attempt."
    },
    {
      "requirement_id": "KDH-016",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The initiation of federation transactions by VBP as the RP is verified by inspecting the sequence of network requests or the code logic that starts the SSO flow."
    },
    {
      "requirement_id": "KDH-017",
      "methods": [
        "Test"
      ],
      "rationale": "The prevention of information leakage during proofing is verified by submitting incorrect self-asserted information and ensuring the error message does not reveal which specific attribute failed."
    },
    {
      "requirement_id": "KDH-018",
      "methods": [
        "Test"
      ],
      "rationale": "The validation of core attributes against authoritative sources or signed evidence is verified by submitting test data that matches or mismatches the source data and observing the proofing outcome."
    },
    {
      "requirement_id": "KDH-019",
      "methods": [
        "Test"
      ],
      "rationale": "The sending of a proofing notification to a validated address is verified by completing the IAL2 proofing process and checking for the notification at the specified address."
    },
    {
      "requirement_id": "KDH-020",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The prohibition of knowledge-based verification is verified by inspecting the code and configuration to ensure no KBV logic is implemented or enabled."
    },
    {
      "requirement_id": "KDH-021",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The prohibition of email for out-of-band authentication is verified by inspecting the authentication configuration and code to ensure email is not used as an OOB factor."
    },
    {
      "requirement_id": "KDH-022",
      "methods": [
        "Test"
      ],
      "rationale": "The 5-minute validity window for SMS codes is verified by submitting a correct code after 5 minutes and observing the rejection, and before 5 minutes and observing success."
    },
    {
      "requirement_id": "KDH-023",
      "methods": [
        "Test"
      ],
      "rationale": "The single-use nature of SMS codes is verified by submitting a valid code twice within its validity period and observing the rejection of the second attempt."
    },
    {
      "requirement_id": "KDH-024",
      "methods": [
        "Test"
      ],
      "rationale": "The non-resetting of the failed authentication count upon generating a new SMS code is verified by failing authentication, requesting a new code, and checking if the failure count persists."
    },
    {
      "requirement_id": "KDH-025",
      "methods": [
        "Test"
      ],
      "rationale": "The absence of additional password composition requirements is verified by setting passwords that meet length and blocklist criteria but lack specific character classes, and observing their acceptance."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "ETC-001",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement specifies behavioral triggers for establishing communication sessions, which must be verified by simulating each trigger condition and observing the OBU's response."
    },
    {
      "requirement_id": "ETC-002",
      "methods": [
        "Test"
      ],
      "rationale": "This negative requirement prevents duplicate session attempts, which is best verified by attempting to trigger a new session while one is active and confirming the OBU rejects it."
    },
    {
      "requirement_id": "ETC-003",
      "methods": [
        "Test"
      ],
      "rationale": "The logic for terminating existing sessions and handling exceptions during RBC transitions is dynamic behavior that requires testing with specific sequence inputs."
    },
    {
      "requirement_id": "ETC-004",
      "methods": [
        "Test"
      ],
      "rationale": "The sequential steps of session establishment, including retries and version compatibility checks, are observable behaviors that must be tested against a simulated RBC."
    },
    {
      "requirement_id": "ETC-005",
      "methods": [
        "Test"
      ],
      "rationale": "The priority order for selecting the radio system is a decision logic that can be verified by setting different configurations and observing which radio system is selected."
    },
    {
      "requirement_id": "ETC-006",
      "methods": [
        "Test"
      ],
      "rationale": "Memorizing the used radio system is an internal state change that can be verified by checking the stored value or observing subsequent behavior that relies on this memory."
    },
    {
      "requirement_id": "ETC-007",
      "methods": [
        "Test"
      ],
      "rationale": "Aborting session establishment under specific conditions (like desk closure or border crossing) is a reactive behavior that must be tested by injecting these conditions during the setup phase."
    },
    {
      "requirement_id": "ETC-008",
      "methods": [
        "Test"
      ],
      "rationale": "The handling of the special 'last known RBC' identity and the use of stored contact information is a specific input-output behavior that requires testing with crafted trackside orders."
    },
    {
      "requirement_id": "ETC-009",
      "methods": [
        "Test"
      ],
      "rationale": "Ignoring an order when no contact information is stored is a conditional behavior that can be verified by clearing stored data and sending the specific trackside order."
    },
    {
      "requirement_id": "ETC-010",
      "methods": [
        "Test"
      ],
      "rationale": "The immediate reconnection attempt using the previously successful radio system is a reactive behavior triggered by a loss event, which must be tested by simulating connection loss."
    },
    {
      "requirement_id": "ETC-011",
      "methods": [
        "Test"
      ],
      "rationale": "The persistent retry logic until specific termination conditions are met is a time-dependent behavior that requires testing by simulating prolonged connection loss."
    },
    {
      "requirement_id": "ETC-012",
      "methods": [
        "Test"
      ],
      "rationale": "Initiating termination only under specific orders or conditions is a control flow behavior that must be verified by testing both valid and invalid termination triggers."
    },
    {
      "requirement_id": "ETC-013",
      "methods": [
        "Test"
      ],
      "rationale": "The repetition of the termination message upon lack of acknowledgement is a timing-based behavior that can be tested by simulating a non-responsive RBC."
    },
    {
      "requirement_id": "ETC-014",
      "methods": [
        "Test"
      ],
      "rationale": "Considering the session terminated after a defined number of retries is a state transition that can be verified by observing the OBU's state after the retry limit is reached."
    },
    {
      "requirement_id": "ETC-015",
      "methods": [
        "Test"
      ],
      "rationale": "Ordering GSM-R registration at specific events (power-up, network change, trackside order) is a behavioral requirement that must be tested by triggering these events."
    },
    {
      "requirement_id": "ETC-016",
      "methods": [
        "Test"
      ],
      "rationale": "Using the default Radio Network type when no other information is available is a fallback behavior that can be verified by clearing stored data and observing the OBU's configuration."
    },
    {
      "requirement_id": "ETC-017",
      "methods": [
