      "id": "TC-ETC-041-03",
      "title": "Relocation of 'max' location item with FRBG accuracy adjustment",
      "covers": [
        "ETC-041"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The train passes a new balise group which becomes the new SOLR. There is a 'max' location item referred to the old SOLR (FRBG). The last relocation of this item was performed per clause 3.6.4.2.5 c) towards a BG not received earlier than the reference BG of this item. Linking information is available for the distance between FRBG and the new SOLR.",
      "test_inputs": "",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "The OBU evaluates the 'max' location item.",
          "expected": "The OBU relocates the 'max' location item by subtracting the distance between FRBG and the new SOLR (from linking info) augmented by twice the location accuracy of the FRBG from the item's distance to the FRBG."
        }
      ]
    },
    {
      "id": "TC-ETC-041-04",
      "title": "Relocation using travelled distance when linking is not available",
      "covers": [
        "ETC-041"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The train passes a new balise group which becomes the new SOLR. There is location-based information referred to the old SOLR (FRBG). Linking information is not available or not known for the distance between FRBG and the new SOLR (e.g., repositioning BG encountered).",
      "test_inputs": "",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "The OBU evaluates the location-based information.",
          "expected": "The OBU relocates the location item by subtracting the estimated, min, or max travelled distance between the FRBG and the new SOLR (computed from train front end positions) from the item's distance to the FRBG, depending on the item type."
        }
      ]
    }
  ]
