{
  "test_cases": [
    {
      "id": "TC-KDH-012-01",
      "title": "Notification sent via independent channel upon authenticator binding",
      "covers": [
        "KDH-012"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "An active company representative account with a registered email address and a valid second-factor authenticator (e.g., TOTP) bound. The representative is authenticated at AAL2.",
      "test_inputs": "",
      "assumptions": "The 'independent mechanism' is implemented as an email notification to the registered address, distinct from the in-session UI or the binding transaction channel.",
      "steps": [
        {
          "no": 1,
          "action": "Initiate the binding of a new authenticator (e.g., a new passkey or TOTP app) to the account.",
          "expected": "The binding process proceeds and completes successfully."
        },
        {
          "no": 2,
          "action": "Check the registered email inbox of the company representative.",
          "expected": "A notification email is received informing the representative that a new authenticator has been added to their account."
        },
        {
          "no": 3,
          "action": "Verify that the notification was not delivered via the same session or interface used to perform the binding (e.g., not just a toast message in the browser where the binding occurred).",
          "expected": "The notification is confirmed to be delivered through an independent channel (email) separate from the binding transaction."
        }
      ]
    },
    {
      "id": "TC-KDH-012-02",
      "title": "Notification triggered for each new authenticator addition",
      "covers": [
        "KDH-012"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "An active company representative account with one authenticator bound. The representative is authenticated at AAL2.",
      "test_inputs": "",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Bind a second authenticator to the account.",
          "expected": "The binding succeeds."
        },
        {
          "no": 2,
          "action": "Check the independent notification channel (e.g., email).",
          "expected": "A notification is received for the addition of the second authenticator."
        },
        {
          "no": 3,
          "action": "Bind a third authenticator to the account.",
          "expected": "The binding succeeds."
        },
        {
          "no": 4,
          "action": "Check the independent notification channel (e.g., email).",
          "expected": "A new notification is received for the addition of the third authenticator, confirming that the notification is triggered for every addition, not just the first."
        }
      ]
    }
  ]
}

