{
  "test_cases": [
    {
      "id": "TC-ETC-050-01",
      "title": "MA rejection when SSP/gradient does not cover full length (Non-infill MA)",
      "covers": [
        "ETC-050"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "Level 2, train in FS mode. A communication session with the RBC is established. The train is stationary or moving slowly.",
      "test_inputs": "An MA message where the SSP and gradient data provided covers only 50% of the distance from the estimated train front end to the Supervised Location (SvL).",
      "assumptions": "The 'full length' for a non-infill MA is defined as the distance from the estimated front end of the train to the supervised location.",
      "steps": [
        {
          "no": 1,
          "action": "The RBC sends a new MA with associated SSP and gradient data that does not cover the full length of the MA (from estimated train front end to SvL).",
          "expected": "The OBU rejects the MA. The previous MA (if any) remains valid, or the train remains in its current state without adopting the new MA. The driver is informed of the error or the MA is not displayed as active."
        },
        {
          "no": 2,
          "action": "Check the OBU status regarding the Movement Authority.",
          "expected": "The OBU does not supervise the new MA. The target speed and target distance are not updated to reflect the rejected MA."
        }
      ]
    },
    {
      "id": "TC-ETC-050-02",
      "title": "MA rejection when SSP/gradient does not cover full length (Infill MA)",
      "covers": [
        "ETC-050"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "Level 1 or 2, train in FS mode. An infill MA is expected. The train is approaching the infill location.",
      "test_inputs": "An infill MA message where the SSP and gradient data covers only a portion of the distance from the infill location reference to the Supervised Location (SvL).",
      "assumptions": "The 'full length' for an infill MA is defined as the distance from the infill location reference to the supervised location.",
      "steps": [
        {
          "no": 1,
          "action": "The RBC sends an infill MA with associated SSP and gradient data that does not cover the full length of the MA (from infill location reference to SvL).",
          "expected": "The OBU rejects the infill MA. The previous MA remains valid. The train continues to be supervised by the previous MA."
        },
        {
          "no": 2,
          "action": "Verify the train supervision limits.",
          "expected": "The Supervised Location (SvL) and Indication Supervision Limit (ISL) remain those of the previous MA. The new infill MA is not applied."
        }
      ]
    },
    {
      "id": "TC-ETC-050-03",
      "title": "MA rejection when SSP/gradient does not cover full length (Supervised Manoeuvre, opposite orientation)",
      "covers": [
        "ETC-050"
      ],
      "type": "Hata",
      "priority": "Orta",
      "preconditions": "Level 2, train in FS mode. A Supervised Manoeuvre (SH) is initiated. The train orientation is about to change or has changed such that the validity direction of the MA is opposite to the current train orientation.",
      "test_inputs": "An MA for a Supervised Manoeuvre where the SSP and gradient data does not cover the full length from the estimated front end of the train (derived from the new orientation) to the Supervised Location.",
      "assumptions": "The 'full length' for this case is defined as the distance from the estimated front end of the train derived from the new train orientation to the supervised location.",
      "steps": [
        {
          "no": 1,
          "action": "The RBC sends an MA for a Supervised Manoeuvre with validity direction opposite to the current train orientation. The SSP and gradient data does not cover the full length from the estimated front end (new orientation) to the SvL.",
          "expected": "The OBU rejects the MA. The train does not enter the Shunting mode or does not adopt the new MA for the manoeuvre."
        },
        {
          "no": 2,
          "action": "Check the OBU response to the manoeuvre request.",
          "expected": "The OBU informs the RBC of the rejection or maintains the previous state. The train remains in its previous mode (e.g., FS) and is supervised by the previous MA."
        }
      ]
    },
    {
      "id": "TC-ETC-050-04",
      "title": "MA acceptance when SSP/gradient covers full length (Boundary)",
      "covers": [
        "ETC-050"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "Level 2, train in FS mode. Communication session established.",
      "test_inputs": "An MA message where the SSP and gradient data covers exactly the full length of the MA (from estimated train front end to SvL) with no gap.",
      "assumptions": "The SSP and gradient data ends exactly at the Supervised Location.",
      "steps": [
        {
          "no": 1,
          "action": "The RBC sends a new MA with SSP and gradient data that covers exactly the full length of the MA (from estimated train front end to SvL).",
          "expected": "The OBU accepts the MA. The new MA becomes the active MA."
        },
        {
          "no": 2,
          "action": "Verify the supervision limits.",
          "expected": "The OBU supervises the train according to the new MA, with the SvL and ISL updated to the values of the new MA."
        }
      ]
    }
  ]
}

