{
  "test_cases": [
    {
      "id": "TC-ETC-074-01",
      "title": "Acceptance of MA shortening when train is in rear of Indication supervision limit",
      "covers": [
        "ETC-074"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "Level 2, communication session with RBC established. Train is running in a mode with a valid MA (e.g., FS). The current MA has an EOA/LOA at a known distance ahead. The train front end position is estimated to be significantly in rear of the proposed shortened MA's Indication supervision limit.",
      "test_inputs": "RBC sends a 'Request to shorten MA' message containing a proposed shortened MA with an EOA closer to the train than the current EOA, including a mode profile and a list of balise groups for SH area.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "The RBC sends a request to shorten the MA with a proposed shortened MA where the Indication supervision limit is ahead of the train's estimated front end position.",
          "expected": "The OBU accepts the request. The proposed shortened MA, its mode profile, and the list of balise groups for SH area are stored as the new MA data."
        },
        {
          "no": 2,
          "action": "The OBU sends a response to the RBC regarding the shortening request.",
          "expected": "The OBU informs the RBC that the request has been accepted (e.g., via a 'Train Accepted' or specific acknowledgement message)."
        }
      ]
    },
    {
      "id": "TC-ETC-074-02",
      "title": "Rejection of MA shortening when train is in advance of Indication supervision limit",
      "covers": [
        "ETC-074"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "Level 2, communication session with RBC established. Train is running in a mode with a valid MA. The train front end position is estimated to be in advance of (or at) the proposed shortened MA's Indication supervision limit.",
      "test_inputs": "RBC sends a 'Request to shorten MA' message containing a proposed shortened MA with an Indication supervision limit located behind the train's estimated front end position.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "The RBC sends a request to shorten the MA with a proposed shortened MA where the Indication supervision limit is in rear of the train's estimated front end position.",
          "expected": "The OBU rejects the request. The previously received MA, mode profile, and list of balise groups for SH area remain valid and unchanged."
        },
        {
          "no": 2,
          "action": "The OBU sends a response to the RBC regarding the shortening request.",
          "expected": "The OBU informs the RBC that the request has been rejected (e.g., via a 'Train Rejected' message)."
        }
      ]
    },
    {
      "id": "TC-ETC-074-03",
      "title": "Boundary condition: Train front end exactly at Indication supervision limit",
      "covers": [
        "ETC-074"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "Level 2, communication session with RBC established. Train is running in a mode with a valid MA. The train front end position is estimated to be exactly at the proposed shortened MA's Indication supervision limit.",
      "test_inputs": "RBC sends a 'Request to shorten MA' message containing a proposed shortened MA where the Indication supervision limit coincides with the train's estimated front end position.",
      "assumptions": "The requirement states 'in rear' for acceptance and 'in advance' for rejection. The behavior at the exact limit is interpreted as not being 'in rear', thus triggering rejection to ensure safety.",
      "steps": [
        {
          "no": 1,
          "action": "The RBC sends a request to shorten the MA with a proposed shortened MA where the Indication supervision limit is exactly at the train's estimated front end position.",
          "expected": "The OBU rejects the request (as the train is not in rear of the limit). The previous MA remains valid."
        },
        {
          "no": 2,
          "action": "The OBU sends a response to the RBC.",
          "expected": "The OBU informs the RBC that the request has been rejected."
        }
      ]
    }
  ]
}

