{
  "test_cases": [
    {
      "id": "TC-KDH-009-01",
      "title": "Changing the pre-registered telephone number requires the full binding process",
      "covers": [
        "KDH-009"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "An active company representative account at AAL2 with an existing pre-registered telephone number for SMS. The representative is authenticated in a session with sufficient privileges to manage authenticators.",
      "test_inputs": "A new, valid telephone number for the representative.",
      "assumptions": "The system implements the binding process as defined in NIST SP 800-63B-4 §4.1.2, which includes authentication at the required AAL and verification of the new authenticator (e.g., via a one-time code sent to the new number).",
      "steps": [
        {
          "no": 1,
          "action": "Initiate the process to change the pre-registered telephone number for SMS codes to a new number.",
          "expected": "The system initiates the binding process for a new authenticator, requiring authentication at the maximum AAL available or required for the new authenticator, and prompts for verification of the new number (e.g., sending a one-time code to the new number)."
        },
        {
          "no": 2,
          "action": "Complete the verification step by entering the one-time code sent to the new telephone number.",
          "expected": "The binding process completes successfully. The new telephone number is now the pre-registered number for SMS codes, and the old number is no longer valid for SMS authentication."
        }
      ]
    },
    {
      "id": "TC-KDH-009-02",
      "title": "Changing the telephone number without completing the binding process is rejected",
      "covers": [
        "KDH-009"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "An active company representative account at AAL2 with an existing pre-registered telephone number for SMS. The representative is authenticated in a session.",
      "test_inputs": "A new, valid telephone number for the representative.",
      "assumptions": "The system enforces the binding process strictly and does not allow bypassing verification steps.",
      "steps": [
        {
          "no": 1,
          "action": "Initiate the process to change the pre-registered telephone number for SMS codes to a new number.",
          "expected": "The system initiates the binding process and prompts for verification of the new number."
        },
        {
          "no": 2,
          "action": "Do not complete the verification step (e.g., do not enter the one-time code or enter an incorrect code) and attempt to finalize the change.",
          "expected": "The system rejects the change. The pre-registered telephone number remains the old number. An error message indicating that the binding process was not completed is displayed."
        }
      ]
    }
  ]
}

